-                return comparison(plannerContext.getMetadata(), operator, cast, originalRight);
+                return Optional.empty();
             }

             if (targetType.isOrderable()) {
@@ -477,7 +478,7 @@ public class UnwrapCastInComparison

                 if (literalVsRoundtripped > 0) {
