+package org.apache.iceberg;
+
+import static org.apache.iceberg.BaseTransaction.TransactionType.SIMPLE;
+
+public final class IcebergTransactions
+{
+    private IcebergTransactions() {}
+
+    /**
+     * Starts a transaction on the metadata the table already holds, like {@link Table#newTransaction()} without the refresh.
+     */
+    public static Transaction newTransaction(BaseTable table)
+    {
+        TableOperations operations = table.operations();
+        return new BaseTransaction(table.name(), operations, SIMPLE, operations.current(), table.reporter());
+    }
